SELECT CASE WHEN orders.shipping_fee >= 42 THEN 'high' WHEN orders.shipping_fee >= 9 THEN 'mid' ELSE 'low' END AS shipping_fee_bucket, COUNT(CASE WHEN shipments.status = 'RETURNED' THEN 1 END) AS returned_count FROM shipments INNER JOIN orders ON shipments.order_id = orders.id WHERE shipments.carrier <> 'Kerry' GROUP BY CASE WHEN orders.shipping_fee >= 42 THEN 'high' WHEN orders.shipping_fee >= 9 THEN 'mid' ELSE 'low' END HAVING COUNT(CASE WHEN shipments.status = 'RETURNED' THEN 1 END) >= 4 ORDER BY returned_count DESC, shipping_fee_bucket;
